import sys

MOD = 10**9 + 7
n = int(sys.stdin.read().split()[0])
count = 0
for mask in range(1 << n):
    bal = 0
    ok = True
    for i in range(n):
        if (mask >> i) & 1:
            bal += 1
        else:
            bal -= 1
        if bal < 0:
            ok = False
            break
    if ok and bal == 0:
        count += 1
print(count % MOD)

